// Original nested-area artwork. Geometry carries the same meaning without color.
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function fieldGrid(c,plan,caption='Our field'){
 const w=480,h=240,x=8,y=8,cw=w/c.columns,rh=h/c.rows,first=plan.columnsTaken*cw,taken=plan.rowsTaken*rh;
 const cells=[];for(let row=0;row<c.rows;row++)for(let col=0;col<c.columns;col++)cells.push(`<rect data-field-cell="${col},${row}" data-first="${col<plan.columnsTaken}" data-taken="${col<plan.columnsTaken&&row<plan.rowsTaken}" x="${x+col*cw}" y="${y+row*rh}" width="${cw}" height="${rh}" fill="${col<plan.columnsTaken?'#d9e9bd':'#fff'}"/>`);
 const stripes=[];for(let a=6;a<first;a+=12)stripes.push(`<path d="M${x+a} ${y}v${h}" stroke="#8ca568" stroke-width="1"/>`);
 const hatch=[];for(let a=-h;a<first;a+=14){const start=Math.max(0,a),end=Math.min(first,a+taken);if(end>start)hatch.push(`<path d="M${x+start} ${y+taken-(start-a)}L${x+end} ${y+taken-(end-a)}" stroke="#665185" stroke-width="4"/>`);}
 const cuts=[];for(let n=1;n<c.columns;n++)cuts.push(`<path d="M${x+n*cw} ${y}v${h}"/>`);for(let n=1;n<c.rows;n++)cuts.push(`<path d="M${x} ${y+n*rh}h${w}"/>`);
 const desc=`Original whole field, ${c.columns} equal columns and ${c.rows} equal rows. First amount: ${plan.columnsTaken}/${c.columns} of the original field, with vertical stripes. Take ${plan.rowsTaken}/${c.rows} of that first amount, with diagonal hatch. ${plan.columnsTaken*plan.rowsTaken} of ${c.columns*c.rows} equal cells taken.`;
 return `<figure class="field-figure"><figcaption>${esc(caption)} <span>Original whole field</span></figcaption><svg class="field-grid" viewBox="0 0 496 256" role="img" aria-label="${esc(caption+'. '+desc)}"><title>${esc(caption)}</title><desc>${esc(desc)}</desc>${cells.join('')}${stripes.join('')}${hatch.join('')}<g stroke="#203c53" stroke-width="1.5" fill="none">${cuts.join('')}</g>${first?`<rect data-field-first-boundary x="${x}" y="${y}" width="${first}" height="${h}" fill="none" stroke="#526a37" stroke-width="4"/>`:''}${first&&taken?`<rect data-field-taken-boundary x="${x}" y="${y}" width="${first}" height="${taken}" fill="none" stroke="#665185" stroke-width="4" stroke-dasharray="8 3"/>`:''}<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="none" stroke="#203c53" stroke-width="5"/></svg></figure>`;
}
